@startuml

class Doctor {
  + practitionerNumber : int
  + signature : string
  + fullName : string
  + address : string
  + phoneNumber : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
}

class Test {
  + duration : int
}

class TestGroup {
  + name : string
}

class RepetitionPattern {
  + interval : string
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class Lab {
  + address : string
  + registrationNumber : string
  + businessHoursStart : time
  + businessHoursEnd : time
  + cancellationFee : float
}

class TestResult {
  + isPositive : boolean
  + report : string
}

class AppointmentType {
  + isWalkInOnly : boolean
  + requiresSampleDropOff : boolean
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Requisition "0..1" -- "0..1" RepetitionPattern : follows
Requisition "1" -- "0..*" Appointment : generates
Patient "1" -- "*" Appointment : books
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers
Test "1" -- "0..1" AppointmentType : has
Test "1" -- "0..*" TestResult : produces
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views

@enduml

